-- ============================================================================
-- دمج خمس صفحات مكرّرة — نقل حقائق لا إعادة صياغة (2026-08-05)
-- ============================================================================
-- خمسة أزواج من الصفحات كانت تتنافس على نفس الاستعلام، فتقسم الترتيب بينها
-- ولا تفوز أيّها. القائمة والقرار مبنيّان على فحص العناوين والتصنيفات لكل
-- الـ355 مقالاً، ثم قراءة محتوى كل مرشّح.
--
-- ثلاثة عناقيد رُفضت صراحةً ولم تُدمج، وهي التي كان الدمج فيها سيُتلف الموقع:
--   • أضنة/هاتاي/مرسين — ثلاث مدن بقالب واحد، لا تكرار.
--   • كهرباء CK / ماء İSKİ — خدمتان مختلفتان.
--   • السيارات المسجّلة باسمك / خطوط الجوال — موضوعان مختلفان.
--
-- القاعدة الحاكمة هنا: الجولة الأولى من الدمج فشلت لأنّها أعادت كتابة الصفحة
-- الباقية، وكل خطأ فيها جاء من النصّ الجديد لا من قرار الدمج. فهذا الملف
-- مولَّد آلياً ولا يكتب جملة واحدة: ينقل عناصر القوائم وقيم الحقول حرفياً،
-- ويُسقط ما تقوله الصفحة الباقية أصلاً (مطابقة بعد تطبيع الهمزة والتاء
-- المربوطة، أو تقاطع كلمات ≥60%).
--
-- تعديلان آليان فقط، وكلاهما شكلي لا لفظي:
--   • حذف ترقيم قديم في أول الخطوة المنقولة («1. ») كي لا يُطبع «6. 1. ».
--   • الحقائق الموجودة في متن الصفحة المحذوفة وحدها تُنقل إلى tips حرفياً،
--     لأنّ الأعمدة لا تحملها وحذف الصفحة كان سيفقدها.
--
-- التحويلات ليست هنا: المشروع يحوّل عبر next.config.ts (تعمل بـ308 على
-- الحافّة). شغّل هذا الملف بعد اكتمال نشر الشيفرة كي لا تصير الروابط 404.
-- ============================================================================

-- school-registration-turkey  ←  school-registration
UPDATE articles SET
    documents = ARRAY['بطاقة الكملك أو إقامة الطفل', 'صور شخصية (2 نسخ)', 'شهادة ميلاد الطفل (أو وثيقة من الكملك)', 'شهادة مدرسية سابقة إن وُجدت (مترجمة)', 'هوية الطفل (كملك/إقامة/هوية) إن وجدت + هويات الأبوين.', 'وثيقة عنوان/سند إقامة (Yerleşim Yeri Belgesi) أو إثبات عنوان من النفوس.', 'شهادة/وثائق المدرسة السابقة + ترجمة عند الحاجة.', 'وثيقة معادلة (Denklik) إذا طُلبت للصف/المرحلة.', 'بطاقة لقاحات/سجل صحي (قد يُطلب حسب المدرسة/المرحلة).']::text[],
    steps = ARRAY['حدد أقرب مدرسة حكومية لمنزلك', 'توجه للمدرسة مع الأوراق المطلوبة', 'قدّم طلب التسجيل لإدارة المدرسة', 'قد يُطلب اختبار تحديد مستوى للأطفال الأكبر سناً', 'استلم جدول الدوام وابدأ الدراسة', 'ثبت عنوانك في النفوس أولاً لأن المدرسة تُحدد حسب المنطقة المسجلة.', 'اسأل المدرسة القريبة أو مديرية التربية عن المدرسة المخصصة لعنوانك (خصوصاً عند الانتقال).', 'إذا طُلبت معادلة (Denklik): جهّز الأوراق وراجع مديرية التربية للحصول عليها.', 'قدّم ملف التسجيل في المدرسة مع جميع النسخ، واطلب قائمة نواقص مكتوبة إن وُجدت.', 'تابع قرار التسجيل/الصف، واحتفظ بأي رقم طلب أو وثيقة استلام.']::text[],
    tips = ARRAY['التعليم مجاني تماماً في المدارس الحكومية', 'إذا لم يتقبل طفلك اللغة التركية بسرعة، اسأل عن فصول الدعم (Uyum Sınıfı)', 'بعض المدارس توفر وجبات غداء مجانية', 'ابدأ مبكراً قبل بداية العام الدراسي لأن المواعيد والضغط تكون أعلى في سبتمبر.', 'الاسم وتاريخ الميلاد يجب أن يطابقا الهوية حرفياً لتجنب تأخير إدخال النظام.', 'التسجيل المدرسي يرتبط مباشرةً بعنوانك المثبت في النفوس (Nüfus) لأنه يحدد “مدرسة المنطقة”.', 'قد تحتاج أيضاً إلى معادلة شهادة (Denklik) أو وثائق من المدرسة السابقة.', 'كثير من المشاكل تأتي من عنوان غير مثبت أو وثائق ناقصة، لذلك جهّز ملفاً كاملاً قبل الذهاب.']::text[],
    fees = 'مجاني.',
    source = 'https://meb.gov.tr',
    last_update = CURRENT_DATE
WHERE slug = 'school-registration-turkey';

-- travel-permit  ←  travel-permit-medical + travel-permit-visit
UPDATE articles SET
    documents = ARRAY['شيفرة e-Devlet.', 'بطاقة الحماية المؤقتة (كملك).', 'وثيقة سبب السفر (حسب الحالة): إذن عمل/SGK، إحالة أو تقرير طبي (Sevk)، موعد قنصلية، دعوة/موعد معرض أو فعالية، وثيقة وفاة، أو وثائق لمّ شمل/دفتر عائلة تركي (عند الانطباق).', 'إذا كنت ستسافر بسيارتك: رقم اللوحة (Araç Plaka).', 'تقرير طبي أو إحالة من مشفى حكومي', 'صورة الكملك']::text[],
    steps = ARRAY['سجّل دخولك إلى e-Devlet وابحث عن: “Yabancılar İçin Yol İzin Belge Başvurusu”.', 'اضغط “Yeni Başvuru” لإنشاء طلب جديد.', 'قبل تعبئة الطلب: قيّم الولاية المقصودة إن كانت “مفتوحة” أو من الولايات المحظورة/الحساسة (القوائم قد تتغير).', 'اختر سبب السفر في خانة “Talep Nedeni”. للولايات المفتوحة: غالباً خيار “زيارة (Ziyaret)” هو المسار المعتاد. للولايات الحساسة: اختر السبب الأقوى الذي ينطبق عليك (عمل/صحة/لم شمل/تعليم/غيره) وأرفق وثائقه الرسمية.', 'حدد الولاية المراد زيارتها والفترة/التاريخ.', 'أدخل رقم لوحة السيارة إذا كان السفر بسيارة خاصة.', 'أرفق وثيقة داعمة في خانة “Ek Belgeler”، ثم أرسل الطلب وتابع النتيجة.', 'احصل على إحالة طبية (Sevk) من مشفى حكومي في ولايتك', 'ادخل بوابة e-Devlet وابحث عن (Yol İzin Belgesi)', 'أرفق الإحالة الطبية مع الطلب', 'انتظر الموافقة (سريعة للحالات الطارئة)', 'اختر سبب الطلب: زيارة (Ziyaret)', 'حدد الولاية المراد السفر إليها وتاريخ الذهاب والعودة', 'أدخل معلومات المضيف (اسمه ورقم TC الخاص به)', 'انتظر الرد (قد يستغرق 1-5 أيام)']::text[],
    tips = ARRAY['للولايات المفتوحة: اطلب مدة منطقية وسبباً واضحاً (زيارة) مع ملف مرتب وواضح.', 'للولايات الحساسة: “زيارة” لوحدها قد لا تكفي؛ جهّز مبرراً قوياً ووثيقة رسمية واضحة.', 'قد تصل نتيجة الطلب عبر SMS أو تظهر ضمن الطلبات في e-Devlet.', 'قد تختلف الشروط حسب الولاية والمرحلة الزمنية، لذلك احتفظ بصورة من الطلب والوثائق المرفقة ولا تعتمد على تجارب قديمة.', 'تأكد أن التقرير الطبي واضح ومختوم لتسريع الموافقة', 'في حالات الإسعاف الطارئ جداً يُسمح بالسفر بدون إذن مسبق', 'الإذن مجاني تماماً', 'قدّم الطلب قبل موعد سفرك بـ 3 أيام على الأقل', 'يمكن للمسؤولين رفض الإذن دون ذكر أسباب', 'إذا كنت بحاجة لعلاج غير متوفر في ولايتك، يمكنك طلب إذن سفر طبي عبر e-Devlet.', 'يمكنك طلب إذن سفر لزيارة عائلية أو أغراض شخصية عبر بوابة e-Devlet.', 'طلبات السفر للولايات المحظورة (مثل إسطنبول وأنقرة) تُرفض غالباً.']::text[],
    warning = 'يُمنع السفر للعلاج بدون إذن مسبق إلا في حالات الإسعاف الطارئ جداً.',
    last_update = CURRENT_DATE
WHERE slug = 'travel-permit';

-- edevlet-tuketici-sikayet  ←  consumer-rights-complaint
UPDATE articles SET
    documents = ARRAY['حساب e‑Devlet فعّال (شيفرة أو بنك أو طرق الدخول المتاحة).', 'رقم الهوية (T.C.) أو رقم الأجنبي (YKN) حسب حالتك.', 'رقم هاتف فعّال (قد تحتاجه للتحقق عبر SMS).', 'تفاصيل الشكوى (اسم الشركة/المنتج/التاريخ/المبلغ).', 'إثباتات إن وُجدت (فاتورة/صور/مراسلات).', 'فاتورة الشراء (Fiş/Fatura).', 'صور للمنتج المعيب.', 'صورة المحادثات مع البائع (إن وجدت).', 'شيفرة إي دولات.']::text[],
    steps = ARRAY['سجّل الدخول إلى e‑Devlet عبر الرابط الرسمي.', 'ابدأ شكوى جديدة ثم املأ البيانات المطلوبة.', 'أرفق الإثباتات إن طُلبت ثم أرسل الشكوى.', 'تابع حالة الشكوى من ملفك داخل e‑Devlet.', 'الدخول لخدمة "Tüketici Hakem Heyeti Başvuru" في e-Devlet.', 'تعبئة بيانات البائع (من الفاتورة).', 'شرح المشكلة وتحميل الصور.', 'انتظار القرار (1-6 أشهر).']::text[],
    tips = ARRAY['إذا لم تفتح الخدمة من المتصفح، جرّب تطبيق e‑Devlet ثم أعد المحاولة.', 'إن ظهرت رسالة “لا تملك صلاحية”، فقد تكون الخدمة غير متاحة لنوع هويتك أو لولايتك.', 'احتفظ بنسخة PDF/Barcode عند استخراج أي وثيقة رسمية.', 'لا تتنازل عن حقك، القانون التركي صارم جداً مع البائعين في حال وجود عيب مصنعي.', 'يمكنك طلب استرداد المال أو استبدال المنتج.', 'هيئة التحكيم للمستهلك هي جهة حكومية تحل الخلافات مجاناً.']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'edevlet-tuketici-sikayet';

-- birth-registration-turkey  ←  newborn-registration
UPDATE articles SET
    documents = ARRAY['شهادة الولادة من المستشفى (الأصل)', 'بطاقة كملك الأب والأم', 'دفتر العائلة السوري أو عقد الزواج', 'صور شخصية للطفل (2 نسخ)', 'شهادة الميلاد الأصلية']::text[],
    steps = ARRAY['احصل على شهادة الولادة من المستشفى (Doğum Belgesi)', 'توجه لمديرية النفوس خلال 30 يوماً', 'قدّم الأوراق المطلوبة لتسجيل المولود', 'توجه لمديرية الهجرة لإصدار كملك للطفل', 'استلم بطاقة الكملك الخاصة بالطفل', 'شهادة الولادة: احصل عليها من المشفى فور الولادة (Doğum Belgesi).', 'النفوس: سجل الطفل في دائرة النفوس.', 'إدارة الهجرة: احجز موعد تحديث بيانات (إضافة مولود) لاستخراج الكملك.']::text[],
    tips = ARRAY['لا تتأخر عن 30 يوماً — التأخير يعقّد الإجراءات', 'سجّل الطفل في القنصلية السورية أيضاً إن أمكن', 'اطلب شهادة ميلاد تركية (Doğum Belgesi) — ستحتاجها للمدرسة لاحقاً', 'الطفل يتبع وضع والديه القانوني.', 'تأكد من كتابة الاسم بدقة في المشفى.', 'يجب تسجيل المولود خلال 30 يوماً من الولادة للحصول على الكملك وتفادي الغرامات.']::text[],
    source = 'إدارة الهجرة',
    last_update = CURRENT_DATE
WHERE slug = 'birth-registration-turkey';

-- edevlet-mobil-hat-sorgulama  ←  mobile-lines-check
UPDATE articles SET
    documents = ARRAY['حساب e‑Devlet فعّال (شيفرة أو بنك أو طرق الدخول المتاحة).', 'رقم الهوية (T.C.) أو رقم الأجنبي (YKN) حسب حالتك.', 'رقم هاتف فعّال (قد تحتاجه للتحقق عبر SMS).', 'رقم TC/هوية لإتمام الدخول.', 'في حال وجود خط غير معروف: وثيقة هوية + معلومات الخط عند مراجعة الشركة.']::text[],
    steps = ARRAY['افتح الرابط الرسمي وسجّل الدخول.', 'راجع قائمة الخطوط المسجلة باسمك.', 'إن وجدت خطاً غير معروف، تواصل مع المشغل فوراً لتصحيح الوضع.', 'سجّل دخولك إلى e-Devlet.', 'ابحث عن “Mobil Hat Sorgulama”.', 'إذا وجدت خطاً غير معروف: راجع شركة الاتصالات فوراً لإلغائه وتثبيت الأمر.']::text[],
    tips = ARRAY['إذا لم تفتح الخدمة من المتصفح، جرّب تطبيق e‑Devlet ثم أعد المحاولة.', 'إن ظهرت رسالة “لا تملك صلاحية”، فقد تكون الخدمة غير متاحة لنوع هويتك أو لولايتك.', 'احتفظ بنسخة PDF/Barcode عند استخراج أي وثيقة رسمية.', 'اجعل الفحص دورياً خصوصاً بعد فقدان هوية/سيم.', 'من المهم فحص الخطوط المسجلة باسمك بشكل دوري، لأن وجود خط غير معروف قد يسبب مشاكل كبيرة.', 'يمكنك التحقق عبر e-Devlet بالبحث عن خدمات الاستعلام عن الخطوط (Mobil Hat Sorgulama).']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'edevlet-mobil-hat-sorgulama';

-- الصفحات المدموجة تُحذف بعد نقل حقائقها
DELETE FROM articles WHERE slug IN ('school-registration', 'travel-permit-medical', 'travel-permit-visit', 'consumer-rights-complaint', 'newborn-registration', 'mobile-lines-check');

-- ═══════════════════════════════════════════════════════════════════════════
-- التحقّق — الأول خمسة صفوف، والثاني يجب أن يرجع صفر صفوف
SELECT slug,
       coalesce(array_length(documents,1),0) AS docs,
       coalesce(array_length(steps,1),0)     AS steps,
       coalesce(array_length(tips,1),0)      AS tips,
       (fees IS NOT NULL) AS has_fees, last_update
FROM articles
WHERE slug IN ('school-registration-turkey', 'travel-permit', 'edevlet-tuketici-sikayet', 'birth-registration-turkey', 'edevlet-mobil-hat-sorgulama')
ORDER BY slug;

SELECT slug FROM articles WHERE slug IN ('school-registration', 'travel-permit-medical', 'travel-permit-visit', 'consumer-rights-complaint', 'newborn-registration', 'mobile-lines-check');
